import{bV as o,aL as c,u as i,G as l}from"./chunks/framework.BfzMay2U.js";const _=JSON.parse('{"title":"阿里编码规范说明","description":"","frontmatter":{"title":"阿里编码规范说明","date":"2026-09-21T22:31:11.000Z"},"headers":[],"relativePath":"java/shortlink/consitution.md","filePath":"java/shortlink/consitution.md"}'),d={name:"java/shortlink/consitution.md"};function t(a,e,r,n,s,u){return c(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="阿里云编码规范说明" tabindex="-1">阿里云编码规范说明 <a class="header-anchor" href="#阿里云编码规范说明" aria-label="Permalink to &quot;阿里云编码规范说明&quot;">​</a></h1><ul><li>任何框架，不要使用过多的侵入或者框架定制化深的内容，防止后续改动耦合性高，成本大。</li><li>N 方库说明 <ul><li>一方库：本工厂内部子项目模块依赖的库 <code>jar</code>包</li><li>二方库：公司内部发布到中央仓库，可供公司内部其他应用依赖的库<code>jar</code>包</li><li>三方库：公司之外的开源库 <code>jar</code>包</li></ul></li><li><code>POJO</code>实体类：专指只有<code>setter/getter/toString</code>的简单类，包括<code>DO/DTO/BO/VO</code>等，禁止命名成<code>xxxPOJO</code></li><li>一定要避免单点故障 <ul><li>一个微服务起码两个人熟悉，一个是主程一个是技术<code>leader</code>，推荐是团队里面的 2 个开发人员</li></ul></li><li>领域模型命名规约 <ul><li>数据对象：<code>xxDO</code>，<code>xx</code>即为数据库表名</li><li>一般数据传输对象：<code>xxxDTO</code>，<code>xxx</code>为业务领域相关的名称，项目里面也使用<code>VO</code></li><li>展示对象：<code>xxxVO</code>，也就是响应给前端的实体包装类</li><li>接受前端<code>json</code>对象请求的命名为：<code>xxxRequest</code></li></ul></li><li>Manager 层：通用业务处理层 <ul><li>对第三方平台封装的层，预处理返回结果以及转化异常信息</li><li>对<code>service</code>层通用能力的下沉，如缓存方案、中间件通用处理</li><li>与<code>DAO</code>层交互，对多个<code>DAO</code>的组合复用</li></ul></li><li><code>DAO</code>层：数据访问层，与底层<code>MySQL</code>、<code>Oracle</code>、<code>Hbase</code>进行数据交互</li><li>外部接口或第三方平台：包括其他部门的<code>RPC</code>开放接口，基础平台，其他公司的<code>HTTP</code>接口</li></ul>',2)])])}const O=o(d,[["render",t]]);export{_ as __pageData,O as default};
